<?php
require __DIR__ . '/../app/bootstrap.php';
$u=require_role(['owner','admin']);
$msg=null;$error=null;
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf();$action=(string)($_POST['action']??'');
  if($action==='save'){
   skynoc_smtp_save(['enabled'=>!empty($_POST['enabled']),'host'=>$_POST['host']??'','port'=>$_POST['port']??587,'encryption'=>$_POST['encryption']??'tls','username'=>$_POST['username']??'','password'=>$_POST['password']??'','from_email'=>$_POST['from_email']??'','from_name'=>$_POST['from_name']??'SkyNoc']);
   $msg='SMTP settings saved.';
  }
  if($action==='test'){
   $to=trim((string)($_POST['test_email']??''));
   if(!filter_var($to,FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Enter a valid test email address.');
   if(!skynoc_send_email($to,'SkyNoc SMTP test','This is a test email from your SkyNoc SMTP configuration.')) throw new RuntimeException('SMTP test failed. Check the SMTP host, port, encryption, credentials and server error log.');
   $msg='SMTP test email sent successfully.';
  }
 }
}catch(Throwable $e){$error=$e->getMessage();error_log('SkyNoc SMTP settings: '.$e->getMessage());}
$s=skynoc_smtp_settings();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SMTP Settings — SkyNoc</title><link rel="stylesheet" href="/admin-page-ui.css"><style>.wrap{max-width:980px;margin:30px auto;padding:0 16px}.hero{background:linear-gradient(135deg,#101828,#1d4ed8);color:#fff;border-radius:20px;padding:28px;margin-bottom:18px}.hero h1{margin:8px 0}.hero p{color:#d0d5dd}.card{background:#fff;border:1px solid #e4e7ec;border-radius:16px;padding:22px;margin-bottom:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.full{grid-column:1/-1}label{display:block;font-size:12px;font-weight:750;margin:0 0 6px;color:#344054}input,select{width:100%;padding:11px 12px;border:1px solid #d0d5dd;border-radius:9px;font:inherit}.row{display:flex;align-items:center;gap:10px}.row input[type=checkbox]{width:auto}.btn{display:inline-block;border:0;border-radius:9px;padding:11px 16px;background:#465fff;color:#fff;font-weight:750;cursor:pointer}.btn.secondary{background:#fff;color:#344054;border:1px solid #d0d5dd}.msg,.err{padding:12px;border-radius:10px;margin-bottom:15px}.msg{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}.hint{color:#667085;font-size:12px;line-height:1.6}.secret{background:#fffaeb;border:1px solid #fedf89;color:#92400e;padding:12px;border-radius:10px}@media(max-width:700px){.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><div class="top"><strong>SkyNoc / Admin</strong><span><?=e($u['name'])?> · <a href="/admin">Dashboard</a> · <a href="/admin/settings">Settings</a></span></div><main class="wrap"><section class="hero"><div style="font-size:12px;font-weight:800;letter-spacing:.08em">EMAIL DELIVERY</div><h1>SMTP Server Settings</h1><p>Configure the SMTP server used for reseller and platform email notifications.</p></section><?php if($msg):?><div class="msg">✓ <?=e($msg)?></div><?php endif;?><?php if($error):?><div class="err">! <?=e($error)?></div><?php endif;?><form method="post" class="card"><h2>SMTP configuration</h2><p class="hint">TLS is recommended. For port 465 use SSL. The password is kept server-side and is never shown in the form.</p><div class="grid"><div class="full row"><input type="checkbox" id="enabled" name="enabled" value="1" <?=$s['enabled']?'checked':''?>><label for="enabled" style="margin:0">Enable SMTP email delivery</label></div><div><label>SMTP Host</label><input name="host" value="<?=e((string)$s['host'])?>" placeholder="smtp.example.com"></div><div><label>Port</label><input type="number" name="port" min="1" max="65535" value="<?=e((string)$s['port'])?>"></div><div><label>Encryption</label><select name="encryption"><option value="tls" <?=$s['encryption']==='tls'?'selected':''?>>STARTTLS / TLS</option><option value="ssl" <?=$s['encryption']==='ssl'?'selected':''?>>SSL</option><option value="none" <?=$s['encryption']==='none'?'selected':''?>>None</option></select></div><div><label>SMTP Username</label><input name="username" value="<?=e((string)$s['username'])?>" autocomplete="off"></div><div><label>SMTP Password</label><input type="password" name="password" value="" placeholder="Leave blank to keep existing password" autocomplete="new-password"></div><div><label>From Email</label><input type="email" name="from_email" value="<?=e((string)$s['from_email'])?>" placeholder="no-reply@example.com"></div><div><label>From Name</label><input name="from_name" value="<?=e((string)$s['from_name'])?>" placeholder="SkyNoc"></div><div class="full"><button class="btn" type="submit">Save SMTP settings</button></div></div><input type="hidden" name="action" value="save"><?=csrf_field()?></form><section class="card"><h2>Send test email</h2><p class="hint">Save the SMTP settings first, then send a test message to verify the configuration.</p><form method="post" class="grid"><div><label>Test recipient</label><input type="email" name="test_email" placeholder="you@example.com" required></div><div style="display:flex;align-items:flex-end"><button class="btn secondary" type="submit">Send test email</button></div><input type="hidden" name="action" value="test"><?=csrf_field()?></form></section><div class="secret"><b>Recommended:</b> SMTP credentials should be dedicated to SkyNoc and should not be committed to GitHub or stored in public configuration files.</div></main></body></html>